def check_blocks(apps, schema_editor):
    """Stop rather than change saved study time: list any block the new rules would reject."""
    Block = apps.get_model("pulse", "AvailabilityBlock")

    def minutes(t):
        return t.hour * 60 + t.minute

    bad = []
    for b in Block.objects.all():
        end = 24 * 60 if b.end_time == datetime.time(0) else minutes(b.end_time)
        if not 0 <= b.weekday <= 6 or end - minutes(b.start_time) < 30:
            bad.append(b)
    if bad:
        rows = ", ".join(f"#{b.id} (student {b.student_id})" for b in bad[:10])
        raise RuntimeError(
            f"{len(bad)} availability blocks are shorter than 30 minutes or have a bad weekday: "
            f"{rows}. Fix or delete them in Django admin, then run migrate again."
        )


def create_onboarding(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    Onboarding = apps.get_model("pulse", "Onboarding")
    for user in User.objects.filter(role="student").select_related("profile"):
        done = getattr(getattr(user, "profile", None), "onboarding_done", False)
        Onboarding.objects.get_or_create(
            student=user,
            defaults={
                "current_step": 5 if done else 1,
                "completed_steps": [1, 2, 3, 4, 5] if done else [],
            },
        )


